from test_bufftap import test, tests
from test_nearby import setup

R=setup+"local B=BuffTap; local r=B.nearbyFrame.rows[1]; local act=r.action; "
CLICK="r.scripts.PreClick(r,'LeftButton',true); "
test('Cast result is on by default',"assert(BuffTap.db.nearbyCastResult==true)")
test('A successful Nearby cast flashes green with the buff name',R+CLICK+"B.nearbyEvents.scripts.OnEvent(nil,'UNIT_SPELLCAST_SUCCEEDED','player','cast',act.id); local o=r.result; assert(o and o.shown,'no overlay'); assert(o.text.text:find(act.name,1,true) and o.text.text:find('done',1,true), o.text.text); assert(o.mark.texture:find('Ready',1,true))")
test('The row stays while the result shows, then clears',R+CLICK+"B.nearbyEvents.scripts.OnEvent(nil,'UNIT_SPELLCAST_SUCCEEDED','player','cast',act.id); aura('nameplate1',5232,'Mark of the Wild'); aura('nameplate1',467,'Thorns'); B.nearbySnapshot=nil; refresh(); assert(r.shown and r.result.shown); advance(1.2); refresh(); assert(r.result.shown,'gone before the GCD ended'); advance(.4); refresh(); assert(not (r.result and r.result.shown))")
test('A failed cast shows the game reason in red',R+CLICK+"B.nearbyEvents.scripts.OnEvent(nil,'UI_ERROR_MESSAGE',51,'Out of range.'); local o=r.result; assert(o and o.shown and o.text.text:find('Out of range',1,true) and not o.text.text:find('%.$'), o and o.text.text); assert(o.mark.texture:find('NotReady',1,true))")
test('A spell failure without a message says Failed',R+CLICK+"B.nearbyEvents.scripts.OnEvent(nil,'UNIT_SPELLCAST_FAILED','player','cast',act.id); advance(.15); assert(r.result and r.result.shown and r.result.text.text=='Failed')")
test('Other spells do not count as the result',R+CLICK+"B.nearbyEvents.scripts.OnEvent(nil,'UNIT_SPELLCAST_SUCCEEDED','player','cast',99999); assert(not (r.result and r.result.shown))")
test('Cast results can be turned off',R+"B.db.nearbyCastResult=false; "+CLICK+"B.nearbyEvents.scripts.OnEvent(nil,'UNIT_SPELLCAST_SUCCEEDED','player','cast',act.id); assert(not (r.result and r.result.shown)); B:Options(); assert(B.options.nearbyCastResult and B.options.nearbyCastResult.checked==false)")
test('Long buff names fit the row',"local fs={}; fs.SetFont=function(s,p,size) s.size=size end; fs.SetText=function(s,t) s.text=t end; fs.GetText=function(s) return s.text end; fs.GetStringWidth=function(s) return #s.text*6*(s.size/12) end; local t=BuffTap.NearbyFitText(fs,150,{'Greater Blessing of Wisdom: done','Greater Blessing of Wisdom'},'f',12,''); assert(t=='Greater Blessing of Wisdom',t); local t2=BuffTap.NearbyFitText(fs,80,{'Greater Blessing of Wisdom: done','Greater Blessing of Wisdom'},'f',12,''); assert(t2:sub(-3)=='...' and #t2*6*(fs.size/12)<=80, t2)")
from test_nearby_cleanse import N
test('A Nearby cleanse result names the debuff',N+"debuff('nameplate1',8552,'Curse of Weakness','Curse',60); refresh(); local r=B.nearbyFrame.rows[1]; r.scripts.PreClick(r,'LeftButton',true); B.nearbyEvents.scripts.OnEvent(nil,'UNIT_SPELLCAST_SUCCEEDED','player','cast',2782); assert(r.result and r.result.shown and r.result.text.text=='Cleansed: Curse of Weakness', r.result and r.result.text.text)")
test('Keybind Nearby cleanse also reports its result',N+"debuff('nameplate1',8552,'Curse of Weakness','Curse',60); refresh(); B.button.scripts.PreClick(B.button,'LeftButton',true); B.nearbyEvents.scripts.OnEvent(nil,'UNIT_SPELLCAST_SUCCEEDED','player','cast',2782); local r=B.nearbyFrame.rows[1]; assert(r.result and r.result.shown)")
test('The flash follows the spell cooldown when the GCD is readable',R+"local t0=now; "+CLICK+"C_Spell=C_Spell or {}; C_Spell.GetSpellCooldown=function() return {startTime=t0,duration=1.0} end; advance(.1); B.nearbyEvents.scripts.OnEvent(nil,'UNIT_SPELLCAST_SUCCEEDED','player','cast',act.id); local u=B.nearbyResult.untilTime; assert(math.abs(u-(t0+1.0))<.01, u-t0)")
test('The list holds still while a result shows',R+"local first=r.entry.guid; "+CLICK+"B.nearbyEvents.scripts.OnEvent(nil,'UNIT_SPELLCAST_SUCCEEDED','player','cast',act.id); assert(B:NearbyResultActive()); local out=B:NearbyDisplayList({}); assert(out[1] and out[1].entry.guid==first)")
test('A failed row can be clicked again straight away',R+"ERR_OUT_OF_RANGE='Out of range.'; "+CLICK+"B.nearbyEvents.scripts.OnEvent(nil,'UI_ERROR_MESSAGE',51,'Out of range.'); B.castRetry={[act.targetGUID..':'..act.id]={untilTime=GetTime()+10,reason='ERR_OUT_OF_RANGE'}}; B.nearbyNeedCache={}; B.nearbySnapshot=nil; refresh(); assert(B:CastRetryBlocked(act),'no retry block to lift'); assert(r.shown and r.result.shown and r.action, 'failed row lost its action'); r.scripts.PreClick(r,'LeftButton',true); assert(r.attrs.type1=='macro' and not (B.nearbyResult and B.nearbyResult.state=='fail'))")
test('Target cleanse stays quiet right after a Nearby cleanse',"local B=BuffTap; B.nearbyQuietCast={recipient='G1',previous='G0',untilTime=GetTime()+5}; assert(B:ReminderSoundAllowed({source='cleanse',target='target',targetGUID='G1'})==false); assert(B:ReminderSoundAllowed({source='cleanse',target='party1',targetGUID='G1'})==true)")
